insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('sj-perfis','sj-perfis',false,307200,array['image/jpeg']);
create policy sj_perfil_ler on storage.objects for select to authenticated using(bucket_id='sj-perfis' and name=(select auth.uid())::text||'/avatar.jpg');
create policy sj_perfil_inserir on storage.objects for insert to authenticated with check(bucket_id='sj-perfis' and name=(select auth.uid())::text||'/avatar.jpg' and exists(select 1 from public.motoristas m where m.auth_user_id=(select auth.uid()) and m.status='ativo'));
create policy sj_perfil_atualizar on storage.objects for update to authenticated using(bucket_id='sj-perfis' and name=(select auth.uid())::text||'/avatar.jpg' and exists(select 1 from public.motoristas m where m.auth_user_id=(select auth.uid()) and m.status='ativo')) with check(bucket_id='sj-perfis' and name=(select auth.uid())::text||'/avatar.jpg' and exists(select 1 from public.motoristas m where m.auth_user_id=(select auth.uid()) and m.status='ativo'));
